import{_ as s,o as a,c as t,a3 as n}from"./chunks/framework.BLaSdaBb.js";const u=JSON.parse('{"title":"出站","description":"","frontmatter":{},"headers":[],"relativePath":"transport/nacp/outbound.md","filePath":"transport/nacp/outbound.md","lastUpdated":1788343005000}'),d={name:"transport/nacp/outbound.md"};function p(o,e,c,i,r,l){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="出站" tabindex="-1">出站 <a class="header-anchor" href="#出站" aria-label="Permalink to &quot;出站&quot;">​</a></h1><p>NACP 出站族函数负责构造 NACPMessage 并提交发送。</p><h2 id="nacp-出站具体方法" tabindex="-1">NACP 出站具体方法 <a class="header-anchor" href="#nacp-出站具体方法" aria-label="Permalink to &quot;NACP 出站具体方法&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>尽管可以直接使用<code>NApp.nacp.xxx</code>直接访问nacp并发送消息，但是通常来讲不建议这么做，会丢失NApp Stream等封装。</p></div><table tabindex="0"><thead><tr><th>方法</th><th>返回</th><th>返回时机</th><th>通常由谁调用</th></tr></thead><tbody><tr><td><code>register</code></td><td><code>Promise&lt;boolean&gt;</code></td><td><code>ACK</code> + <br> <code>RES</code></td><td><code>NApp.connect()</code></td></tr><tr><td><code>unregister</code></td><td><code>Promise&lt;ResponseMessage&gt;</code></td><td><code>ACK</code> + <br> <code>RES</code></td><td><code>NApp.disconnect()</code> / <code>terminate()</code></td></tr><tr><td><code>request</code></td><td><code>Promise&lt;ResponseMessage&gt;</code></td><td><code>ACK</code> + <br> <code>RES</code></td><td><code>NApp.request()</code></td></tr><tr><td><code>response</code></td><td><code>Promise&lt;boolean&gt;</code></td><td><code>ACK</code></td><td>Processor 回调 / <code>NApp.response()</code></td></tr><tr><td><code>subscribe</code></td><td><code>Promise&lt;ResponseMessage&gt; | void</code></td><td><code>ACK</code> + <br> <code>RES</code></td><td><code>NApp.subscribe()</code> / NACP 内部</td></tr><tr><td><code>unsubscribe</code></td><td><code>Promise&lt;ResponseMessage&gt; | void</code></td><td><code>ACK</code> + <br> <code>RES</code></td><td><code>NApp.unsubscribe()</code> / NACP 内部</td></tr><tr><td><code>notify</code></td><td><code>Promise&lt;boolean&gt;</code></td><td>-</td><td>订阅转发 / <code>NApp.notify()</code></td></tr><tr><td><code>signal</code></td><td><code>Promise&lt;boolean&gt;</code></td><td><code>ACK</code></td><td><code>NApp.signal()</code></td></tr><tr><td><code>ack</code></td><td><code>Promise&lt;boolean&gt;</code></td><td>-</td><td>NACP 入站流程</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>目标暂时离线时，可靠消息可以进入积压表等待重连。消息进入积压表不代表上述 Promise 已经完成。</p><p>具体的离线、补发和超时行为见<a href="/transport/nacp/lifecycle">生命周期</a>。</p><p><code>request</code> 等待业务的最终 Response，因此没有处理时限。</p><p><code>register</code>、<code>unregister</code>、<code>subscribe</code> 和 <code>unsubscribe</code> 等待协议操作的 Response，超时为 10 秒。</p></div><h2 id="nacp-出站" tabindex="-1">NACP 出站 <a class="header-anchor" href="#nacp-出站" aria-label="Permalink to &quot;NACP 出站&quot;">​</a></h2><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NApp.nacp.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">outbound</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  NACPMessage,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  opt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> boolean</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>outbound()</code> 是所有 NACP 消息共用的底层提交入口，所有的具体方法都是通过这一入口完成提交。</p><p>它接收一条已经构造完成的 <a href="/transport/nacp/message"><code>NACPMessage</code></a>，根据 <code>message.to</code> 选择路由，并将消息放入积压表或提交给 NACT。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>message</code></td><td>NACPMessage完整对象</td></tr><tr><td><code>opt.peerId</code></td><td>绕过 App 路由，直接向指定 NACT Peer 发送</td></tr><tr><td><code>opt.forwarded</code></td><td>标记为 Gateway 转发消息，不进入本地积压与 ACK 跟踪</td></tr><tr><td><code>opt.retransmit</code></td><td>标记为积压消息重发，避免重复加入积压表</td></tr></tbody></table><p>返回 <code>true</code> 只表示消息已被 NACP 接纳，目标离线、消息仍停留在积压表时也会返回 <code>true</code>。</p><p>返回 <code>false</code> 表示消息因发给自己、没有路由、发送失败或容量限制而未被接纳。</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><strong>一般情况下不应直接调用</strong> <code>NApp.nacp.outbound()</code>。</p><p>它只负责提交一条已经构造好的消息，不会执行各具体出站方法的配套副作用，包括：</p><ul><li>不会为 Request、Subscribe 等消息建立 Response 等待记录；</li><li>不会为可靠消息建立可供调用方等待的 ACK Promise；</li><li>不会建立或清理 Subscribe / AutoSubscribe 的本地记录；</li><li>不会执行 Register 的 App-Peer 绑定、身份校验和 Gateway 结算；</li><li>不会执行 Unsubscribe、Response 等方法附带的本地清理；</li><li>不会替调用方构造、补全或校验 NACPMessage。</li></ul><p>直接用<code>outbound</code>发送消息，线上确实可能会出现对应数据，但本地状态与回包无法正确关联。</p><p>除 NACP 内部路由、重发和 Gateway 转发外，应使用对应的NACP具体出站方法。</p></div><h2 id="路由" tabindex="-1">路由 <a class="header-anchor" href="#路由" aria-label="Permalink to &quot;路由&quot;">​</a></h2><p>NACP 根据消息信封中的 <code>to</code> 选择路由。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标是自己</span></span>
<span class="line"><span>  → 拒绝发送</span></span>
<span class="line"><span></span></span>
<span class="line"><span>目标未知，但本 App 已连接 Gateway</span></span>
<span class="line"><span>  → 交给 Gateway 转发</span></span>
<span class="line"><span></span></span>
<span class="line"><span>目标未知，且本 App 未连接 Gateway</span></span>
<span class="line"><span>  → 拒绝发送</span></span>
<span class="line"><span></span></span>
<span class="line"><span>目标已知且在线</span></span>
<span class="line"><span>  → 通过目标对应的 Peer 发送</span></span>
<span class="line"><span></span></span>
<span class="line"><span>目标已知但离线</span></span>
<span class="line"><span>  → 进入 backlog，等待目标重连</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>Gateway 只负责转发，不会修改消息的 <code>from</code> 和 <code>to</code>。</p><p>Gateway 的使用方式见 <a href="/napp/advanced/gateway">NApp Gateway</a>。</p><p>接收方如何处理这些消息见<a href="/transport/nacp/inbound">入站族函数</a>，出站错误与观测事件见<a href="/transport/nacp/observability">可观测</a>。</p><p>各消息的字段与协议语义见对应子页面。</p>`,21)])])}const h=s(d,[["render",p]]);export{u as __pageData,h as default};
